<script setup>
import { CircleDollarSign, Save } from '@lucide/vue';
import { onMounted, reactive, ref } from 'vue';
import AppButton from '../../components/ui/AppButton.vue';import AppInput from '../../components/ui/AppInput.vue';import { api,getApiError } from '../../services/api.js';import { useUiStore } from '../../stores/ui.js';
const fares=ref([]),editing=ref(null),form=reactive({}),loading=ref(true),saving=ref(false);const ui=useUiStore();
async function load(){loading.value=true;try{const response=await api.get('/admin/fares');fares.value=response.data.data.fares}finally{loading.value=false}}
function edit(fare){editing.value=fare;Object.assign(form,{minimumFare:fare.minimumFare,baseFare:fare.baseFare,baseDistanceKm:fare.baseDistanceKm,perKilometerRate:fare.perKilometerRate,sharedPassengerDiscountRate:fare.sharedPassengerDiscountRate??0,effectiveFrom:new Date().toISOString()})}
async function save(){saving.value=true;try{await api.patch(`/admin/fares/${editing.value._id}`,{minimumFare:Number(form.minimumFare),baseFare:Number(form.baseFare),baseDistanceKm:Number(form.baseDistanceKm),perKilometerRate:Number(form.perKilometerRate),sharedPassengerDiscountRate:Number(form.sharedPassengerDiscountRate),effectiveFrom:form.effectiveFrom});editing.value=null;ui.notify('New fare policy activated.','success');load()}catch(error){ui.notify(getApiError(error).message,'error')}finally{saving.value=false}}onMounted(load);
</script>
<template><section class="page admin-page"><div class="page-header"><div><span class="eyebrow">Pricing policy</span><h1 class="page-title">Fare settings</h1><p class="muted">Changes create a new effective fare record; previous policies remain auditable.</p></div></div><div v-if="loading" class="skeleton" style="height:260px"></div><div v-else class="fare-grid"><article v-for="fare in fares" :key="fare._id" class="fare-card card"><div class="fare-head"><span><CircleDollarSign :size="23" /></span><div><small>{{ fare.rideType==='shared'?'Shared ride':'Private ride' }}</small><strong>₱{{ fare.minimumFare.toFixed(0) }} minimum</strong></div></div><dl><div><dt>Base fare</dt><dd>₱{{ fare.baseFare }}</dd></div><div><dt>Included distance</dt><dd>{{ fare.baseDistanceKm }} km</dd></div><div><dt>Additional km</dt><dd>₱{{ fare.perKilometerRate }}/km</dd></div><div v-if="fare.rideType==='shared'"><dt>Shared discount</dt><dd>{{ Math.round(fare.sharedPassengerDiscountRate*100) }}%</dd></div></dl><AppButton variant="outline" block @click="edit(fare)">Edit fare policy</AppButton></article></div><div v-if="editing" class="modal-backdrop" @click.self="editing=null"><form class="modal card" @submit.prevent="save"><div><span class="eyebrow">{{ editing.rideType==='shared'?'Shared':'Private' }} ride</span><h2>New fare policy</h2></div><div class="form-grid"><AppInput v-model="form.minimumFare" type="number" min="0" label="Minimum fare (₱)" required/><AppInput v-model="form.baseFare" type="number" min="0" label="Base fare (₱)" required/><AppInput v-model="form.baseDistanceKm" type="number" min="0" step="0.1" label="Base distance (km)" required/><AppInput v-model="form.perKilometerRate" type="number" min="0" step="0.1" label="Per kilometer (₱)" required/><AppInput v-if="editing.rideType==='shared'" v-model="form.sharedPassengerDiscountRate" type="number" min="0" max="0.8" step="0.05" label="Discount rate (0–0.8)" required/></div><div class="modal-actions"><AppButton variant="outline" @click="editing=null">Cancel</AppButton><AppButton type="submit" :loading="saving"><template #icon><Save :size="17" /></template>Activate policy</AppButton></div></form></div></section></template>
<style scoped>.admin-page{max-width:1000px}.fare-grid{display:grid;gap:14px}.fare-card{display:grid;gap:16px;padding:18px}.fare-head{display:flex;align-items:center;gap:12px}.fare-head>span{display:grid;width:48px;height:48px;place-items:center;border-radius:15px;background:#d1fae5;color:var(--color-primary-dark)}.fare-head>div{display:grid;gap:3px}.fare-head small{color:var(--color-text-soft)}.fare-head strong{font-size:1rem}dl{display:grid;gap:0;margin:0}dl div{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--color-border);font-size:.75rem}dt{color:var(--color-text-soft)}dd{margin:0;font-weight:750}.modal-backdrop{position:fixed;z-index:1200;inset:0;display:grid;place-items:center;padding:18px;background:rgb(15 23 42/.55)}.modal{display:grid;width:min(100%,620px);max-height:90vh;gap:18px;padding:22px;overflow-y:auto}.modal h2{margin:0}.form-grid{display:grid;gap:15px}.modal-actions{display:flex;justify-content:flex-end;gap:9px}@media(min-width:650px){.fare-grid{grid-template-columns:1fr 1fr}.form-grid{grid-template-columns:1fr 1fr}}</style>

